from __future__ import annotations
import numpy as np
from numpy.typing import NDArray

def spectral_diagnostics(eigenvalues: NDArray[np.complex128], z: complex, n: int) -> dict[str, float]:
    """Calculate phase-locking and square-root-radius diagnostics."""
    values = np.asarray(eigenvalues, dtype=np.complex128)
    if n < 1:
        raise ValueError("n must be positive")
    if z == 0:
        phase = float(np.max(np.abs(values), initial=0.0))
        ratio = 0.0
    else:
        phase = float(np.max(np.abs(np.imag(values * np.conjugate(z))) /
                     (abs(z) * np.maximum(1.0, np.abs(values))), initial=0.0))
        ratio = float(np.max(np.abs(values), initial=0.0) / (abs(z) * np.sqrt(n)))
    return {"maximum_phase_residual": phase, "square_root_radius_ratio": ratio}

from __future__ import annotations
from collections.abc import Sequence

def expected_weighted_pattern_count(edge_counts: Sequence[int], p: float, z: complex) -> complex:
    """Return z times the expected number of prescribed patterns present."""
    if not 0.0 <= p <= 1.0:
        raise ValueError("p must lie in [0, 1]")
    if any(k < 0 for k in edge_counts):
        raise ValueError("edge counts must be nonnegative")
    return z * sum(p ** k for k in edge_counts)

